#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/drivers/uart.h>
#include <zephyr/modem/backend/tty.h>
#include <zephyr/modem/backend/modem_backend.h>

#include "tty_sim.h" /* Assuming this is a local header for simulation */

#define TTY_SIM_UART_NODE DT_NODELABEL(tty_sim_uart)

static struct tty_sim_dev tty_sim_dev_0;
static struct modem_backend_tty_data modem_backend_tty_data_0;

static K_POLL_SIGNAL_DEFINE(ready_signal);
static K_POLL_SIGNAL_DEFINE(rx_rdy_signal);
static K_POLL_SIGNAL_DEFINE(tx_rdy_signal);

static void modem_backend_event_cb(struct modem_backend *backend,
                                   enum modem_backend_event event,
                                   void *user_data)
{
    switch (event) {
    case MODEM_BACKEND_EVENT_READY:
        k_poll_signal_raise(&ready_signal, 0);
        break;
    case MODEM_BACKEND_EVENT_RX_RDY:
        k_poll_signal_raise(&rx_rdy_signal, 0);
        break;
    case MODEM_BACKEND_EVENT_TX_RDY:
        k_poll_signal_raise(&tx_rdy_signal, 0);
        break;
    default:
        break;
    }
}

static void test_close_open(void)
{
    struct modem_backend_tty_data *tty = &modem_backend_tty_data_0;
    int ret;

    /* Ensure backend is started for this test */
    ret = modem_backend_start(&tty->backend);
    zassert_equal(ret, 0, "modem_backend_start failed");

    /* Test close */
    ret = modem_backend_stop(&tty->backend);
    zassert_equal(ret, 0, "modem_backend_stop failed");

    /* Test open */
    ret = modem_backend_start(&tty->backend);
    zassert_equal(ret, 0, "modem_backend_start failed");
}

static void test_receive(void)
{
    struct modem_backend_tty_data *tty = &modem_backend_tty_data_0;
    uint8_t rx_buf[32];
    size_t bytes_read;
    int ret;

    /* Ensure backend is started for this test */
    ret = modem_backend_start(&tty->backend);
    zassert_equal(ret, 0, "modem_backend_start failed");

    /* Simulate data reception */
    tty_sim_write(&tty_sim_dev_0, "AT\r", 3);

    /* Wait for RX_RDY event */
    k_poll_signal_init(&rx_rdy_signal);
    struct k_poll_event events[] = {
        K_POLL_EVENT_INITIALIZER(K_POLL_TYPE_SIGNAL, K_POLL_MODE_NOTIFY_ONLY, &rx_rdy_signal),
    };
    ret = k_poll(events, ARRAY_SIZE(events), K_MSEC(1000));
    zassert_equal(ret, 0, "k_poll for RX_RDY failed");

    /* Read data */
    bytes_read = modem_backend_read(&tty->backend, rx_buf, sizeof(rx_buf));
    zassert_equal(bytes_read, 3, "Did not read 3 bytes");
    zassert_mem_equal(rx_buf, "AT\r", 3, "Received data mismatch");
}

static void test_receive_ready_event_not_raised(void)
{
    struct modem_backend_tty_data *tty = &modem_backend_tty_data_0;
    int ret;

    /* Ensure backend is stopped for this test */
    ret = modem_backend_stop(&tty->backend);
    zassert_equal(ret, 0, "modem_backend_stop failed");

    /* Reset signal */
    k_poll_signal_init(&ready_signal);

    /* Simulate data reception while backend is stopped */
    tty_sim_write(&tty_sim_dev_0, "AT\r", 3);

    /* Poll for READY event (should not be raised) */
    struct k_poll_event events[] = {
        K_POLL_EVENT_INITIALIZER(K_POLL_TYPE_SIGNAL, K_POLL_MODE_NOTIFY_ONLY, &ready_signal),
    };

    ret = k_poll(events, ARRAY_SIZE(events), K_MSEC(100)); /* Short timeout */
    zassert_equal(ret, -EAGAIN, "k_poll unexpectedly detected ready event"); /* Should timeout */

    bool result = (ready_signal.result == 1);
    zassert_false(result, "MODEM_BACKEND_EVENT_READY was unexpectedly raised");
}

static void test_receive_ready_event_raised(void)
{
    struct modem_backend_tty_data *tty = &modem_backend_tty_data_0;
    int ret;

    /* Reset signal for this test run */
    k_poll_signal_init(&ready_signal);

    /* Simulate data reception. This data will be buffered by tty_sim_dev_0. */
    tty_sim_write(&tty_sim_dev_0, "AT\r", 3);

    /* Start the backend, which should raise MODEM_BACKEND_EVENT_READY. */
    /* This ensures the READY event is raised *after* the signal is reset and
     * potentially after data is available for processing. */
    ret = modem_backend_start(&tty->backend);
    zassert_equal(ret, 0, "modem_backend_start failed");

    /* Poll for the READY event */
    struct k_poll_event events[] = {
        K_POLL_EVENT_INITIALIZER(K_POLL_TYPE_SIGNAL, K_POLL_MODE_NOTIFY_ONLY, &ready_signal),
    };

    ret = k_poll(events, ARRAY_SIZE(events), K_MSEC(1000)); /* 1 second timeout */
    zassert_equal(ret, 0, "k_poll failed to detect ready event");

    bool result = (ready_signal.result == 1);
    zassert_true(result, "MODEM_BACKEND_EVENT_READY was not raised after data reception and start");
}

static void test_setup(void)
{
    const struct device *uart_dev = DEVICE_DT_GET(TTY_SIM_UART_NODE);
    zassert_true(device_is_ready(uart_dev), "UART device not ready");

    tty_sim_init(&tty_sim_dev_0, uart_dev);
    modem_backend_tty_init(&modem_backend_tty_data_0, &tty_sim_dev_0);
    modem_backend_register_event_callback(&modem_backend_tty_data_0.backend,
                                           modem_backend_event_cb, NULL);

    /* Ensure backend is stopped at setup, each test will start it if needed. */
    modem_backend_stop(&modem_backend_tty_data_0.backend);
}

static void test_teardown(void)
{
    /* Ensure backend is stopped after each test */
    modem_backend_stop(&modem_backend_tty_data_0.backend);
}

ZTEST_SUITE(modem_backend_tty_suite, NULL, test_setup, NULL, NULL, test_teardown);
